import http from "k6/http";
import { check, sleep } from "k6";
import { config } from "./config.js";

class PerformanceApp {
  constructor() {
    this.response = null;
  }
  requestTarget() {
    this.response = http.get(
      `${config.testData.baseUrl}${config.testData.endpoint}`,
      { tags: { operation: "target" } },
    );
  }
  verifyTarget() {
    check(this.response, {
      "target status is expected": (response) =>
        response.status === config.testData.expectedStatus,
      "target returned a body": (response) => Boolean(response.body),
    });
  }
  waitForThinkTime() {
    sleep(config.testData.thinkTimeSeconds);
  }
  executeTargetJourney() {
    this.requestTarget();
    this.verifyTarget();
    this.waitForThinkTime();
  }
}

export const app = new PerformanceApp();
